  "当前版本 {0}": "Current version {0}",
  "当前环境不支持自动更新，请手动刷新页面": "Automatic updates are not supported here; refresh the page manually",
  "循环小节": "Loop bars",
  "我的琴谱": "My scores",
  "所有设备共用同一个令牌，所以无法单独移除某一台。如果设备丢失或怀疑泄露：到 ": "All devices share one token, so a single device cannot be removed. If a device is lost or you suspect a leak: go to ",
