  "手机扫码登录": "Sign in by scanning with a phone",
  "打开 ": "Open ",
  "找不到仓库或目录：检查令牌是否只授权了正确的私有仓库，以及仓库名有没有改过。": "Repository or folder not found: check that the token is authorised for the right private repository and that the repository was not renamed.",
  "找不到该仓库，或令牌没有访问它的权限": "Repository not found, or the token has no access to it",
