  "备份": "Backup",
  "谱子保存在你的 GitHub 仓库里。备份会把它们全部下载成一个压缩包；恢复会把压缩包里的文件放回仓库。": "Your scores are kept in your GitHub repository. A backup downloads all of them as one zip file; restoring puts the files of a zip back into the repository.",
