  "替换：用新文件覆盖旧的（旧版本仍可在 GitHub 历史里找回）。保留两份：新文件自动改名，比如“名称 (2)”。": "Remplacer : écrase l'ancien fichier (l'ancienne version reste dans l'historique GitHub). Garder les deux : le nouveau est renommé, p. ex. « nom (2) ».",
  "最近打开": "Ouverts récemment",
  "照片将转存为 PDF。": "La photo sera enregistrée au format PDF.",
  "需要先添加转换文件": "Il faut d'abord ajouter le fichier de conversion",
  "你的仓库里还没有 convert.yml，没有它 PDF 无法转换。": "Votre dépôt ne contient pas encore convert.yml ; sans lui, les PDF ne peuvent pas être convertis.",
  "点下面的按钮，GitHub 会打开一个已填好内容的页面，点页面底部的“Commit changes”即可。完成后重新上传 PDF。": "Touchez le bouton ci-dessous : GitHub ouvre une page déjà remplie ; touchez « Commit changes » en bas de cette page. Importez ensuite à nouveau le PDF.",
  "在 GitHub 创建 convert.yml": "Créer convert.yml sur GitHub",
  "③ 创建转换文件 convert.yml：填入你的仓库，点下面的按钮，GitHub 会打开一个已填好内容的页面，点页面底部的“Commit changes”即可。": "③ Créer le fichier de conversion convert.yml : saisissez votre dépôt et touchez le bouton ; GitHub ouvre une page déjà remplie, puis touchez « Commit changes » en bas.",
  "请先填写仓库（用户名/仓库名）": "Saisissez d'abord le dépôt (nom/dépôt)",
  "正在把照片转成 PDF：{0}": "Conversion de la photo en PDF : {0}",
  "无法读取这张照片：{0}": "Cette photo est illisible : {0}",
  "开启 PDF 转换": "Activer la conversion de PDF",
  "注意！": "Attention !",
  "PDF 文件仅可查看，不能播放。": "Un fichier PDF ne peut être que consulté, pas joué.",
  "要转换 PDF，请先在“设置 → PDF 转换”里连接 GitHub。": "Pour convertir des PDF, connectez d'abord GitHub dans « Réglages → Conversion de PDF ».",
  "图片需要先开启 PDF 转换（设置 → PDF 转换）。": "Les photos nécessitent d'activer d'abord la conversion de PDF (Réglages → Conversion de PDF).",
  "将 PDF 转为可播放乐谱": "Transformer un PDF en partition jouable",
  "播放、指法和游戏模式需要 MusicXML 文件 (.musicxml / .mxl), 获取方式如下:": "La lecture, le doigté et le mode jeu nécessitent un fichier MusicXML (.musicxml / .mxl). Pour en obtenir un :",
  " – 现成文件，准确度最高": " – fichiers existants, les plus fiables",
  " – 免费识别软件": " – logiciel de reconnaissance gratuit",
  " – 付费识别软件，通常效果更好": " – logiciels de reconnaissance payants, en général de meilleurs résultats",
  "本 App 的 GitHub 云端转换，使用你自己的仓库和账号额度。": "Conversion cloud GitHub de l'application, avec votre propre dépôt et le quota de votre compte.",
  "设置方法": "Guide de configuration",
  "转换后请先用 MuseScore 等软件校对，再点击右上角“上传琴谱”，选择 .musicxml 或 .mxl 文件。": "Après la conversion, vérifiez le résultat dans MuseScore ou un logiciel similaire, puis touchez « Importer une partition » en haut à droite et choisissez le fichier .musicxml ou .mxl.",
  "上述软件与网站均与本 App 无关，名称仅供参考，费用和条款以其官网为准。PDF 将交由你所选的工具处理，请注意隐私。": "Les logiciels et sites ci-dessus n'ont aucun lien avec l'application ; les noms sont donnés à titre indicatif, les prix et conditions sont ceux de leurs sites. Votre PDF est traité par l'outil que vous choisissez : attention à votre vie privée.",
  "转换结果由算法自动识别，无法保证完全正确，请自行核对。": "Le résultat provient d'une reconnaissance automatique et n'est pas garanti exact ; veuillez le vérifier vous-même.",
  "保存 PDF 仅可查看，不能播放。": "Un PDF enregistré ne peut être que consulté, pas joué.",
  "建议直接上传 MusicXML 文件 (.musicxml / .mxl), 效果最佳。": "Il est recommandé d'importer directement un fichier MusicXML (.musicxml / .mxl) pour un résultat optimal.",
  "处理方式": "Que faire",
  "转换成可播放乐谱，并保留 PDF": "Convertir en partition jouable et garder le PDF",
  "继续": "Continuer",
  "注意：": "Remarque :",
  "转换结果由算法自动识别，无法保证完全正确，请转换后自行核对。": "Le résultat provient d'une reconnaissance automatique et n'est pas garanti exact ; vérifiez-le après la conversion.",
  "仅保存 PDF：": "PDF seul :",
  "只能查看，不能播放，也没有指法。": "consultation seulement : pas de lecture ni de doigtés.",
  "建议：": "Conseil :",
  "直接上传 MusicXML 文件（.musicxml / .mxl），效果最佳。": "importez directement un fichier MusicXML (.musicxml / .mxl) pour un résultat optimal.",
  "播放、指法和游戏模式需要 MusicXML 文件（.musicxml / .mxl）。获取方式：": "La lecture, le doigté et le mode jeu nécessitent un fichier MusicXML (.musicxml / .mxl). Pour en obtenir un :",
  "现成文件（最准确）：": "Fichier existant (le plus fiable) :",
  "软件转换：": "Conversion par logiciel :",
  "免费：": "gratuit :",
  "；付费（通常效果更好）：": " ; payant (en général de meilleurs résultats) :",
  "本 App 的 GitHub 云端转换：": "Conversion cloud GitHub de l'application :",
  "使用你自己的仓库和账号额度。": "Utilise votre propre dépôt et le quota de votre compte.",
  "转换之后：": "Après la conversion :",
  "识别结果常有错误，请先用 MuseScore 等软件校对，再点右上角“上传琴谱”，选择 .musicxml 或 .mxl 文件。": "Les résultats de la reconnaissance contiennent souvent des erreurs : vérifiez-les d'abord dans MuseScore ou un logiciel similaire, puis touchez « Importer une partition » en haut à droite et choisissez le fichier .musicxml ou .mxl.",
  "请先连接 GitHub": "Veuillez d'abord connecter GitHub",
  "读取失败": "Échec de la lecture",
  "上传失败": "Échec de l'envoi",
  "转换失败": "Échec de la conversion",
  "等了 {0} 分钟还没有结果。文件还留在你的仓库的 inbox/ 里，可以到 GitHub 的 Actions 页面看看转换有没有在运行。": "Aucun résultat après {0} minutes. Le fichier est toujours dans le dossier inbox/ de votre dépôt ; consultez la page Actions de GitHub pour voir si la conversion est en cours.",
  "要把 PDF 转成可播放乐谱，需要一个免费的 GitHub 账号和你自己的私有仓库。乐谱仍然只在这台设备上；仓库只是临时中转，转换完就删除。": "Pour transformer un PDF en partition jouable, il faut un compte GitHub gratuit et votre propre dépôt privé. Les partitions restent uniquement sur cet appareil ; le dépôt ne sert que de relais temporaire et est nettoyé après la conversion.",
