  "已取消对齐小节": "Alignement des mesures désactivé",
  "已对齐小节。点旁边的小箭头，可以改每行的小节数。": "Mesures alignées. Touchez la petite flèche à côté du bouton pour changer le nombre de mesures par ligne.",
  "显示简谱（每行谱下面一行数字）": "Afficher la notation chiffrée (une ligne de chiffres sous chaque portée)",
