  "备份": "Sauvegarde",
  "谱子保存在你的 GitHub 仓库里。备份会把它们全部下载成一个压缩包；恢复会把压缩包里的文件放回仓库。": "Vos partitions sont dans votre dépôt GitHub. Une sauvegarde les télécharge toutes dans un fichier zip ; la restauration remet les fichiers du zip dans le dépôt.",
