  "正常几分钟就会完成。可以点卡片上的 ↻ 重试，或到 GitHub 看运行日志找原因。": "Cela prend normalement quelques minutes. Touchez ↻ sur la carte pour réessayer, ou consultez le journal sur GitHub.",
