  "琴谱存放在你的私有 GitHub 仓库中，需要访问令牌才能查看。": "Vos partitions sont dans votre dépôt GitHub privé ; un jeton d'accès est nécessaire pour les voir.",
  "用另一台设备的相机扫描下面的二维码，会自动打开并登录。": "Scannez le QR code ci-dessous avec l'appareil photo d'un autre appareil ; il s'ouvre et se connecte automatiquement.",
