  "该仓库是公开的，琴谱会被所有人看到。请使用私有仓库。": "Ce dépôt est public : tout le monde verrait vos partitions. Utilisez un dépôt privé.",
  "请先登录": "Veuillez d'abord vous connecter",
  "请检查 iPad 的网络，或公司网络是否拦截了 api.github.com。": "Vérifiez le réseau de l'iPad, ou si un réseau d'entreprise bloque api.github.com.",
  "请输入令牌": "Veuillez saisir le jeton",
  "读不到「{0}」的内容。如果它在 iCloud 云盘里，请先在“文件”App 里点它让它下载到本机（图标上的云消失），再重新选择上传。": "Impossible de lire « {0} ». S'il est dans iCloud Drive, touchez-le d'abord dans l'app Fichiers pour le télécharger (le nuage disparaît), puis choisissez-le à nouveau.",
  "读不到文件「{0}」。如果它在 iCloud 里，请先在“文件”App 里点一下把它下载到本机，再重新选择。": "Impossible de lire le fichier « {0} ». S'il est dans iCloud, touchez-le d'abord dans l'app Fichiers pour le télécharger, puis choisissez-le à nouveau.",
  "读取列表失败 ({0})": "Impossible de lire la liste ({0})",
  "读取四手联弹配置失败 ({0})": "Impossible de lire la configuration quatre mains ({0})",
  "起点＝当前小节": "Début = mesure actuelle",
  "跟随系统": "Suivre le système",
  "转换中… {0}": "Conversion… {0}",
  "转换失败，点 ⓘ 查看原因": "Échec de la conversion — touchez ⓘ pour la cause",
  "转换失败：{0}": "Échec de la conversion : {0}",
  "转换成可播放乐谱靠自动识别（需要几分钟），识别结果不一定准，常有音符、调号或节奏出错。保留 PDF 则原样存放，可以像图片谱一样直接看，但不能播放、也没有指法。": "La conversion en partition jouable utilise la reconnaissance automatique (quelques minutes) et n'est pas toujours fiable : notes, armures ou rythmes sont souvent faux. Garder le PDF le conserve tel quel : lisible comme une image, mais sans lecture audio ni doigtés.",
