  "已有一台登录好的设备？在它的“设置 → PDF 转换”里用手机扫码，或复制登录链接粘贴到上面，就不用重新生成令牌。": "Schon auf einem anderen Gerät angemeldet? Scannen Sie unter „Einstellungen → PDF-Umwandlung“ den QR-Code oder kopieren Sie den Anmeldelink und fügen Sie ihn oben ein, ein neuer Token ist dann nicht nötig.",
