  "已有乐谱「{0}」，转换结果会覆盖它。请先改名或删除那份乐谱。": "Die Noten „{0}“ existieren bereits, das Ergebnis würde sie überschreiben. Benennen Sie sie zuerst um oder löschen Sie sie.",
