  "找不到仓库或目录：检查令牌是否只授权了正确的私有仓库，以及仓库名有没有改过。": "Repository oder Ordner nicht gefunden: Prüfen Sie, ob der Token nur für das richtige private Repository freigegeben ist und ob das Repository umbenannt wurde.",
