  "备份": "Sicherung",
  "谱子保存在你的 GitHub 仓库里。备份会把它们全部下载成一个压缩包；恢复会把压缩包里的文件放回仓库。": "Ihre Partituren liegen in Ihrem GitHub-Repository. Eine Sicherung lädt alle als eine Zip-Datei herunter; beim Wiederherstellen kommen die Dateien aus dem Zip zurück ins Repository.",
