  "正在转换，请耐心等待，不要重复上传": "Konvertierung läuft, bitte warten Sie und laden Sie nicht erneut hoch",
  "正常几分钟就会完成。可以点卡片上的 ↻ 重试，或到 GitHub 看运行日志找原因。": "Normalerweise ist es in wenigen Minuten fertig. Tippen Sie auf der Karte auf ↻, um es erneut zu versuchen, oder suchen Sie die Ursache im Ausführungsprotokoll auf GitHub.",
