  "点谱面上的音符，再点数字": "Tippen Sie auf eine Note, dann auf eine Zahl",
  "琴谱仓库": "Noten-Repository",
  "琴谱存放在你的私有 GitHub 仓库中，需要访问令牌才能查看。": "Ihre Noten liegen in Ihrem privaten GitHub-Repository; zum Ansehen ist ein Zugriffstoken nötig.",
  "用另一台设备的相机扫描下面的二维码，会自动打开并登录。": "Scannen Sie den QR-Code unten mit der Kamera eines anderen Geräts; er öffnet sich und meldet automatisch an.",
