  "设置": "Einstellungen",
  "该仓库是公开的，琴谱会被所有人看到。请使用私有仓库。": "Dieses Repository ist öffentlich, sodass alle Ihre Noten sehen könnten. Verwenden Sie ein privates Repository.",
  "请先登录": "Bitte melden Sie sich zuerst an",
  "请检查 iPad 的网络，或公司网络是否拦截了 api.github.com。": "Prüfen Sie das Netzwerk des iPad oder ob ein Firmennetz api.github.com blockiert.",
  "请输入令牌": "Bitte geben Sie den Token ein",
  "读不到「{0}」的内容。如果它在 iCloud 云盘里，请先在“文件”App 里点它让它下载到本机（图标上的云消失），再重新选择上传。": "„{0}“ kann nicht gelesen werden. Liegt die Datei in iCloud Drive, tippen Sie sie zuerst in der App „Dateien“ an, damit sie auf das Gerät geladen wird (das Wolkensymbol verschwindet), und wählen Sie sie dann erneut aus.",
  "读不到文件「{0}」。如果它在 iCloud 里，请先在“文件”App 里点一下把它下载到本机，再重新选择。": "Die Datei „{0}“ kann nicht gelesen werden. Liegt sie in iCloud, tippen Sie sie zuerst in der App „Dateien“ an, um sie herunterzuladen, und wählen Sie sie dann erneut aus.",
  "读取列表失败 ({0})": "Liste konnte nicht gelesen werden ({0})",
  "读取四手联弹配置失败 ({0})": "Vierhändig-Konfiguration konnte nicht gelesen werden ({0})",
  "起点＝当前小节": "Start = aktueller Takt",
  "跟随系统": "System folgen",
  "转换中… {0}": "Wird konvertiert … {0}",
  "转换失败，点 ⓘ 查看原因": "Konvertierung fehlgeschlagen, tippen Sie auf ⓘ für die Ursache",
  "转换失败：{0}": "Konvertierung fehlgeschlagen: {0}",
  "转换成可播放乐谱靠自动识别（需要几分钟），识别结果不一定准，常有音符、调号或节奏出错。保留 PDF 则原样存放，可以像图片谱一样直接看，但不能播放、也没有指法。": "Die Umwandlung in spielbare Noten beruht auf automatischer Erkennung (einige Minuten) und ist nicht immer genau: Noten, Vorzeichen oder Rhythmen sind oft falsch. Wenn Sie die PDF behalten, wird sie unverändert gespeichert: Sie lässt sich wie ein Bild lesen, aber nicht abspielen und hat keinen Fingersatz.",
  "转换成可播放乐谱（识别可能不准）": "In spielbare Noten konvertieren (Erkennung kann ungenau sein)",
  "转换比平时久，可能已经卡住": "Konvertierung dauert länger als üblich, hängt möglicherweise",
  "转换由私有琴谱仓库里的 GitHub 自动任务完成，通常需要几分钟。识别结果可能有错，请打开后核对，必要时在 MuseScore 里修改。": "Die Konvertierung läuft als automatische GitHub-Aufgabe in Ihrem privaten Noten-Repository und dauert meist einige Minuten. Das Ergebnis kann Fehler enthalten: Öffnen Sie es zur Prüfung und korrigieren Sie es bei Bedarf in MuseScore.",
  "返回": "Zurück",
  "还原": "Wiederherstellen",
  "还没有琴谱，点右上角“上传琴谱”（支持 MusicXML / .mxl / PDF）。也可以先": "Noch keine Noten. Tippen Sie oben rechts auf „Noten hochladen“ (MusicXML / .mxl / PDF). Oder zuerst ",
