  "选出两个人各自的谱子：A 在上面一屏，B 在下面一屏。": "Wählen Sie die Noten der beiden Spieler: A auf dem oberen, B auf dem unteren Bildschirm.",
  "通常需要 3–10 分钟。完成后会自动出现在“全部琴谱”里，并弹出提示（请保持此页面打开）。": "Meist 3–10 Minuten. Danach erscheint es automatisch unter „Alle Noten“ mit einem Hinweis (lassen Sie diese Seite geöffnet).",
