  "已对齐小节。点旁边的小箭头，可以改每行的小节数。": "小節をそろえました。ボタンの横の小さな矢印で1行の小節数を変えられます。",
  "显示简谱（每行谱下面一行数字）": "簡譜を表示（各段の下に数字の行）",
