  "添加示例曲目，或点右上角“上传琴谱”（支持 MusicXML / .mxl / PDF）。": "サンプル楽譜を追加するか、右上の「楽譜をアップロード」を押します（MusicXML / .mxl / PDF）。",
  "点开一份谱子，点谱面上的任意位置，就从那里开始播放。": "楽譜を開き、楽譜の好きな場所を押すと、そこから再生します。",
