  "还没有收藏。点卡片上的 ☆ 就能加入收藏。": "아직 즐겨찾기가 없어요. 카드의 ☆를 탭하면 즐겨찾기에 추가돼요.",
  "离线：显示的是上次同步的内容，修改和上传要联网后才能进行": "오프라인: 마지막으로 동기화한 내용을 보여 줘요. 수정과 업로드는 인터넷에 연결해야 해요",
  "还没有琴谱，点右上角“上传琴谱”（支持 MusicXML / .mxl / PDF）。": "아직 악보가 없어요. 오른쪽 위의 \"악보 업로드\"를 탭하세요 (MusicXML / .mxl / PDF 지원).",
  "它是四手联弹「{0}」的一个声部，删除后这首四手联弹也会消失（另一个声部的谱子保留）。": "이 악보는 연탄 곡 「{0}」의 한 파트예요. 삭제하면 이 연탄 곡도 사라져요 (다른 파트의 악보는 남아요).",
  "· 当前 {0}": " · 현재 {0}",
  "删除令牌，所有设备会立即失效，再生成新令牌重新登录即可。": "토큰을 삭제하면 모든 기기가 즉시 로그아웃돼요. 새 토큰을 만들어 다시 로그인하세요.",
