  "GitHub 上的文件刚刚被别处改过，已自动重试仍未成功：请刷新后再试一次。": "GitHub의 파일이 방금 다른 곳에서 변경됐고, 자동으로 다시 시도했지만 실패했어요. 새로고침한 뒤 다시 시도해 주세요.",
  "GitHub 令牌管理": "GitHub 토큰 관리",
  "GitHub 拒绝了请求：可能是令牌没有“Contents: Read and write”权限，或短时间内操作太频繁，等一两分钟再试。": "GitHub가 요청을 거부했어요. 토큰에 \"Contents: Read and write\" 권한이 없거나 짧은 시간에 요청이 너무 많았을 수 있어요. 1~2분 기다렸다가 다시 시도하세요.",
  "GitHub 访问令牌（也可粘贴“登录链接”）": "GitHub 액세스 토큰 (로그인 링크를 붙여 넣어도 돼요)",
