  "、": ", ",
  "「{0}」不是有效的 MusicXML 压缩包（.mxl），文件可能已损坏。请换成 .musicxml 或 .xml 再试。": "「{0}」은(는) 올바른 MusicXML 압축 파일(.mxl)이 아니에요. 파일이 손상됐을 수 있어요. .musicxml 또는 .xml로 다시 시도해 주세요.",
  "「{0}」像是四手联弹的两个声部": "「{0}」은(는) 연탄 곡의 두 파트인 것 같아요",
  "「{0}」已经在转换队列中（转换通常需要 3–10 分钟），不需要重复上传。": "「{0}」은(는) 이미 변환 대기열에 있어요 (보통 3~10분 걸려요). 다시 업로드할 필요가 없어요.",
  "「{0}」的内容不是 MusicXML（找不到 score-partwise），没有上传。请确认导出的是 MusicXML 格式。": "「{0}」의 내용이 MusicXML이 아니에요 (score-partwise를 찾을 수 없어요). 업로드하지 않았어요. MusicXML 형식으로 내보냈는지 확인해 주세요.",
  "一直显示旧版本时使用，不会退出登录": "계속 예전 버전이 보일 때 사용하세요. 로그아웃되지 않아요",
