  "优先级：乐谱里的指法 > 自动建议。自己标注的指法保存后写进乐谱文件，之后读取以它为准。": "우선순위: 악보에 있는 운지법 > 자동 추천. 직접 입력한 운지법은 저장하면 악보 파일에 기록되고, 이후에는 그것을 기준으로 읽어요.",
  "你一次上传了两个文件。如果它们是同一首歌里两个人弹的部分，合成后可以分屏一起练习。": "파일 두 개를 한 번에 업로드했어요. 한 곡을 두 사람이 나눠 치는 파트라면 합쳐서 분할 화면으로 함께 연습할 수 있어요.",
