  "备份": "백업",
  "谱子保存在你的 GitHub 仓库里。备份会把它们全部下载成一个压缩包；恢复会把压缩包里的文件放回仓库。": "악보는 GitHub 저장소에 보관됩니다. 백업은 모든 악보를 하나의 zip 파일로 내려받고, 복원은 zip의 파일을 저장소에 다시 넣습니다.",
