  "正在登录…": "로그인하는 중…",
  "正在转换，请耐心等待，不要重复上传": "변환하는 중이에요. 기다려 주시고 다시 업로드하지 마세요",
  "正常几分钟就会完成。可以点卡片上的 ↻ 重试，或到 GitHub 看运行日志找原因。": "보통 몇 분이면 끝나요. 카드의 ↻를 탭해 다시 시도하거나, GitHub의 실행 로그에서 원인을 확인하세요.",
