  "琴谱存放在你的私有 GitHub 仓库中，需要访问令牌才能查看。": "악보는 비공개 GitHub 저장소에 보관되며, 보려면 액세스 토큰이 필요해요.",
  "用另一台设备的相机扫描下面的二维码，会自动打开并登录。": "다른 기기의 카메라로 아래 QR 코드를 스캔하면 자동으로 열리고 로그인돼요.",
