  "设置": "설정",
  "该仓库是公开的，琴谱会被所有人看到。请使用私有仓库。": "이 저장소는 공개 저장소라서 누구나 악보를 볼 수 있어요. 비공개 저장소를 사용하세요.",
  "请先登录": "먼저 로그인해 주세요",
  "请检查 iPad 的网络，或公司网络是否拦截了 api.github.com。": "iPad의 네트워크를 확인하거나, 회사 네트워크가 api.github.com을 차단하는지 확인하세요.",
  "请输入令牌": "토큰을 입력해 주세요",
  "读不到「{0}」的内容。如果它在 iCloud 云盘里，请先在“文件”App 里点它让它下载到本机（图标上的云消失），再重新选择上传。": "「{0}」을(를) 읽을 수 없어요. iCloud 드라이브에 있다면 먼저 \"파일\" 앱에서 탭해 이 기기로 다운로드한 뒤(아이콘의 구름이 사라져요) 다시 선택해 업로드하세요.",
  "读不到文件「{0}」。如果它在 iCloud 里，请先在“文件”App 里点一下把它下载到本机，再重新选择。": "「{0}」 파일을 읽을 수 없어요. iCloud에 있다면 먼저 \"파일\" 앱에서 탭해 이 기기로 다운로드한 뒤 다시 선택하세요.",
  "读取列表失败 ({0})": "목록을 읽지 못했어요 ({0})",
  "读取四手联弹配置失败 ({0})": "연탄 설정을 읽지 못했어요 ({0})",
  "起点＝当前小节": "시작점 = 현재 마디",
  "跟随系统": "시스템 설정 따르기",
  "转换中… {0}": "변환하는 중… {0}",
  "转换失败，点 ⓘ 查看原因": "변환하지 못했어요. ⓘ를 탭해 원인을 확인하세요",
  "转换失败：{0}": "변환하지 못했어요: {0}",
  "转换成可播放乐谱靠自动识别（需要几分钟），识别结果不一定准，常有音符、调号或节奏出错。保留 PDF 则原样存放，可以像图片谱一样直接看，但不能播放、也没有指法。": "재생 가능한 악보로 변환하는 일은 자동 인식으로 이루어져 몇 분 걸리며, 결과가 항상 정확하지는 않아요. 음표, 조표, 리듬이 틀리는 경우가 많아요. PDF를 보관하면 원본 그대로 저장되어 이미지 악보처럼 볼 수 있지만 재생하거나 운지법을 볼 수는 없어요.",
  "转换成可播放乐谱（识别可能不准）": "재생 가능한 악보로 변환 (인식이 부정확할 수 있어요)",
  "转换比平时久，可能已经卡住": "평소보다 오래 걸려요. 멈췄을 수 있어요",
  "转换由私有琴谱仓库里的 GitHub 自动任务完成，通常需要几分钟。识别结果可能有错，请打开后核对，必要时在 MuseScore 里修改。": "변환은 비공개 악보 저장소의 GitHub 자동 작업으로 이루어지며 보통 몇 분 걸려요. 결과에 오류가 있을 수 있으니 열어서 확인하고, 필요하면 MuseScore에서 수정하세요.",
  "返回": "뒤로",
  "还原": "되돌리기",
  "还没有琴谱，点右上角“上传琴谱”（支持 MusicXML / .mxl / PDF）。也可以先": "아직 악보가 없어요. 오른쪽 위의 \"악보 업로드\"를 탭하세요 (MusicXML / .mxl / PDF 지원). 또는 먼저 ",
  "这个名称不能用（不要包含 / \\ : * ? \" < > |）": "이 이름은 사용할 수 없어요 (/ \\ : * ? \" < > | 는 넣지 마세요)",
  "这份 PDF 怎么处理？": "이 PDF를 어떻게 할까요?",
  "这是一首四手联弹吗？": "연탄 곡인가요?",
  "这首歌的名字": "곡 이름",
